pub struct OdetteEffect {
    pub stellar_glimmer_state: usize,
    pub stellar_conduct_application_count: usize,
    pub marvelous_splendor_self: f64,  // 「华彩」自身平均层数（由用户在角色配置中给出）
    pub marvelous_splendor_other: f64, // 「华彩」其他角色平均层数（奥黛塔后台时转移给队友）
    pub common_data: CharacterCommonData,
}

impl<A: Attribute> ChangeAttribute<A> for OdetteEffect {
    fn change_attribute(&self, attribute: &mut A) {
        // 天赋1：获选者的春祭 — 每层「华彩」使角色星烁反应伤害提升15%
        // 注：华彩层数在召唤后随时间（奥黛塔处于后台时每秒减少并转移给队友）动态变化，
        // 此处分别以「自身平均层数」与「其他角色平均层数」近似计算。
        if self.common_data.has_talent1 {
            // 奥黛塔自身持有的「华彩」
            let self_bonus = self.marvelous_splendor_self * ODETTE_SKILL.p1_stellar_bonus_per_stack;
            if self_bonus > 0.0 {
                attribute.set_value_by_t(
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ReactionEnhance,
                        ReactionType::StellarConduct,
                    )),
                    "奥黛塔天赋1",
                    self_bonus,
                );
                attribute.set_value_by_t(
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ReactionEnhance,
                        ReactionType::StellarSwirl,
                    )),
                    "奥黛塔天赋1",
                    self_bonus,
                );
            }
            // 队伍中其他角色持有的「华彩」（奥黛塔处于后台时转移）
            let other_bonus = self.marvelous_splendor_other * ODETTE_SKILL.p1_stellar_bonus_per_stack;
            if other_bonus > 0.0 {
                attribute.set_value_to_s(
                    CharacterSelector::select_all_except_self(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ReactionEnhance,
                        ReactionType::StellarConduct,
                    )),
                    "奥黛塔天赋1·队友",
                    other_bonus,
                );
                attribute.set_value_to_s(
                    CharacterSelector::select_all_except_self(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ReactionEnhance,
                        ReactionType::StellarSwirl,
                    )),
                    "奥黛塔天赋1·队友",
                    other_bonus,
                );
            }
        }

        // 天赋2：赤忱者的悲歌 — 攻击力超过1000的部分，每100点使星烁反应伤害额外造成原本1.5%的伤害，至多30%
        if self.common_data.has_talent2 {
            let bonus = Arc::new(move |atk: f64, _| {
                if atk > ODETTE_SKILL.p2_base_atk {
                    ((atk - ODETTE_SKILL.p2_base_atk) / 100.0 * ODETTE_SKILL.p2_bonus_per_100_atk)
                        .min(ODETTE_SKILL.p2_bonus_max)
                } else {
                    0.0
                }
            });
            attribute.add_edge_t1(
                AttributeType::Panel(AttributeName::ATK),
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                    AttributeVariableType::ReactionEnhance,
                    ReactionType::StellarConduct,
                )),
                bonus.clone(),
                "奥黛塔天赋2",
                EdgePriority::Invisible,
            );
            attribute.add_edge_t1(
                AttributeType::Panel(AttributeName::ATK),
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                    AttributeVariableType::ReactionEnhance,
                    ReactionType::StellarSwirl,
                )),
                bonus,
                "奥黛塔天赋2",
                EdgePriority::Invisible,
            );
        }

        // 天赋3：星耀祝礼·银晓之舞 — 处于辉映·星超导/星扩散状态时，队伍角色触发超导/冰扩散
        // 转为星超导/星扩散，并基于奥黛塔攻击力提升该反应的基础伤害（每100点攻击力+0.7%，至多14%）
        // 仅增强与当前辉映状态对应的反应（无辉映状态不提供增益）
        let base_bonus = Arc::new(move |atk: f64, _| {
            (atk / 100.0 * ODETTE_SKILL.p3_base_per_100_atk).min(ODETTE_SKILL.p3_base_max)
        });
        if self.stellar_glimmer_state == 1 {
            attribute.add_edge_s1to1(
                CharacterSelector::select_all(attribute),
                AttributeType::Panel(AttributeName::ATK),
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                    AttributeVariableType::ElevativeBase,
                    ReactionType::StellarConduct,
                )),
                base_bonus.clone(),
                "奥黛塔天赋3",
                EdgePriority::Invisible,
            );
        }
        if self.stellar_glimmer_state == 2 {
            attribute.add_edge_s1to1(
                CharacterSelector::select_all(attribute),
                AttributeType::Panel(AttributeName::ATK),
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                    AttributeVariableType::ElevativeBase,
                    ReactionType::StellarSwirl,
                )),
                base_bonus,
                "奥黛塔天赋3",
                EdgePriority::Invisible,
            );
        }

        // 命座2：她想，我要见证雪鹄未见之梦 — 每层「华彩」使角色攻击力提升7%
        if self.common_data.constellation >= 2 {
            // 奥黛塔自身持有的「华彩」
            let self_atk_bonus = self.marvelous_splendor_self * ODETTE_SKILL.c2_atk_per_stack;
            if self_atk_bonus > 0.0 {
                attribute.add_atk_percentage("奥黛塔命座2", self_atk_bonus);
            }
            // 队伍中其他角色持有的「华彩」
            let other_atk_bonus = self.marvelous_splendor_other * ODETTE_SKILL.c2_atk_per_stack;
            if other_atk_bonus > 0.0 {
                attribute.add_atk_percentage_s(
                    CharacterSelector::select_all_except_self(attribute),
                    "奥黛塔命座2·队友",
                    other_atk_bonus,
                );
            }
        }

        // 命座6：伸出手，触及苍穹永恒的面容 — 受「华彩」影响的角色星烁反应伤害擢升25%，
        // 奥黛塔对敌人造成的星烁反应伤害额外擢升20%
        if self.common_data.constellation >= 6 {
            // 奥黛塔自身持有「华彩」：擢升25%，且额外擢升20%
            if self.marvelous_splendor_self > 0.0 {
                attribute.set_value_by_t(
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ElevativeElevate,
                        ReactionType::StellarConduct,
                    )),
                    "奥黛塔命座6",
                    ODETTE_SKILL.c6_elevate_all,
                );
                attribute.set_value_by_t(
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ElevativeElevate,
                        ReactionType::StellarSwirl,
                    )),
                    "奥黛塔命座6",
                    ODETTE_SKILL.c6_elevate_all,
                );
                attribute.set_value_by_t(
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ElevativeElevate,
                        ReactionType::StellarConduct,
                    )),
                    "奥黛塔命座6·自身",
                    ODETTE_SKILL.c6_elevate_self,
                );
                attribute.set_value_by_t(
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ElevativeElevate,
                        ReactionType::StellarSwirl,
                    )),
                    "奥黛塔命座6·自身",
                    ODETTE_SKILL.c6_elevate_self,
                );
            }
            // 队伍中其他角色持有「华彩」：擢升25%
            if self.marvelous_splendor_other > 0.0 {
                attribute.set_value_to_s(
                    CharacterSelector::select_all_except_self(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ElevativeElevate,
                        ReactionType::StellarConduct,
                    )),
                    "奥黛塔命座6·队友",
                    ODETTE_SKILL.c6_elevate_all,
                );
                attribute.set_value_to_s(
                    CharacterSelector::select_all_except_self(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ElevativeElevate,
                        ReactionType::StellarSwirl,
                    )),
                    "奥黛塔命座6·队友",
                    ODETTE_SKILL.c6_elevate_all,
                );
            }
        }

        // 星超导附着次数 → ElevativeCoefficient
        ElevativeReaction::apply_stellar_conduct_extra_coefficient(attribute, self.stellar_conduct_application_count);
    }
}

