    fn change_attribute<A: Attribute>(attribute: &mut A, common_data: &CharacterCommonData, skill_config: &CharacterSkillConfig) {
        let (stellar_glimmer_state, _, _) = match &common_data.config {
            CharacterConfig::Odette { stellar_glimmer_state, .. } => (*stellar_glimmer_state, 0, 0.0),
            _ => (0, 0, 0.0),
        };

        let (activated_coda, has_dance_double, snow_swans_dream_active) = match *skill_config {
            CharacterSkillConfig::Odette { activated_coda, has_dance_double, snow_swans_dream_active } =>
                (activated_coda, has_dance_double, snow_swans_dream_active),
            _ => (false, false, false),
        };
        let _ = activated_coda;

        let (_, _, s3) = common_data.get_3_skill();

        // 命座2：独舞倒影在场且奥黛塔处于辉映·星烁状态时，独舞倒影附近敌人的对应元素抗性降低20%
        // - 辉映·星超导：冰、雷元素抗性降低20%
        // - 辉映·星扩散：冰、风元素抗性降低20%
        if common_data.constellation >= 2 && has_dance_double {
            match stellar_glimmer_state {
                1 => {
                    attribute.set_value_to_s(
                        CharacterSelector::select_all(attribute),
                        AttributeType::Invisible(InvisibleAttributeType::new_element(AttributeVariableType::ResMinus, Element::Cryo)),
                        "奥黛塔命座2",
                        ODETTE_SKILL.c2_res_minus,
                    );
                    attribute.set_value_to_s(
                        CharacterSelector::select_all(attribute),
                        AttributeType::Invisible(InvisibleAttributeType::new_element(AttributeVariableType::ResMinus, Element::Electro)),
                        "奥黛塔命座2",
                        ODETTE_SKILL.c2_res_minus,
                    );
                }
                2 => {
                    attribute.set_value_to_s(
                        CharacterSelector::select_all(attribute),
                        AttributeType::Invisible(InvisibleAttributeType::new_element(AttributeVariableType::ResMinus, Element::Cryo)),
                        "奥黛塔命座2",
                        ODETTE_SKILL.c2_res_minus,
                    );
                    attribute.set_value_to_s(
                        CharacterSelector::select_all(attribute),
                        AttributeType::Invisible(InvisibleAttributeType::new_element(AttributeVariableType::ResMinus, Element::Anemo)),
                        "奥黛塔命座2",
                        ODETTE_SKILL.c2_res_minus,
                    );
                }
                _ => {}
            }
        }

        // 元素爆发：雪鹄之梦 — 提升奥黛塔造成的星烁反应伤害（基于元素爆发等级）
        if snow_swans_dream_active {
            let bonus = ODETTE_SKILL.q_swan_dream_bonus[s3];
            attribute.set_value_by_t(
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                    AttributeVariableType::ReactionEnhance,
                    ReactionType::StellarConduct,
                )),
                "奥黛塔技能Q",
                bonus,
            );
            attribute.set_value_by_t(
                AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                    AttributeVariableType::ReactionEnhance,
                    ReactionType::StellarSwirl,
                )),
                "奥黛塔技能Q",
                bonus,
            );

            // 命座4：奥黛塔获得雪鹄之梦时，队伍中附近的其他角色造成的星烁反应伤害提升，
            // 提升值相当于雪鹄之梦效果的50%
            if common_data.constellation >= 4 {
                let team_bonus = bonus * 0.5;
                attribute.set_value_to_s(
                    CharacterSelector::select_all_except_self(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ReactionEnhance,
                        ReactionType::StellarConduct,
                    )),
                    "奥黛塔命座4",
                    team_bonus,
                );
                attribute.set_value_to_s(
                    CharacterSelector::select_all_except_self(attribute),
                    AttributeType::Invisible(InvisibleAttributeType::new_reaction(
                        AttributeVariableType::ReactionEnhance,
                        ReactionType::StellarSwirl,
                    )),
                    "奥黛塔命座4",
                    team_bonus,
                );
            }
        }
    }

    fn damage_internal<D: DamageBuilder>(context: &DamageContext<'_, D::AttributeType>, s: usize, config: &CharacterSkillConfig, fumo: Option<Element>) -> D::Result {
        let s: OdetteDamageEnum = num::FromPrimitive::from_usize(s).unwrap();
        let (s1, s2, s3) = context.character_common_data.get_3_skill();

        let (stellar_glimmer_state, stellar_conduct_application_count, marvelous_splendor_self, marvelous_splendor_other) = match &context.character_common_data.config {
            CharacterConfig::Odette { stellar_glimmer_state, stellar_conduct_application_count, marvelous_splendor_self, marvelous_splendor_other } =>
                (*stellar_glimmer_state, *stellar_conduct_application_count, *marvelous_splendor_self, *marvelous_splendor_other),
            _ => (0, 0, 0.0, 0.0),
        };
        let _ = (stellar_conduct_application_count, marvelous_splendor_self, marvelous_splendor_other);

        let (activated_coda, has_dance_double, snow_swans_dream_active) = match *config {
            CharacterSkillConfig::Odette { activated_coda, has_dance_double, snow_swans_dream_active } =>
                (activated_coda, has_dance_double, snow_swans_dream_active),
            _ => (false, false, false),
        };
        let _ = snow_swans_dream_active;

        use OdetteDamageEnum::*;
        let mut builder = D::new();

        // 条件检查
        // 破晓终奏相关伤害：需施放特殊元素战技「柔板·破晓终奏」
        if matches!(s, EC_DOT | EC | C1) && !activated_coda {
            return builder.none();
        }
        // 独舞倒影舞步伤害：需独舞倒影在场
        if matches!(s, EP | EW | EP_STELLAR | EW_STELLAR) && !has_dance_double {
            return builder.none();
        }
        // 舞步的星烁额外伤害：需施放特殊元素战技「柔板·破晓终奏」，且处于辉映·星烁状态
        if matches!(s, EP_STELLAR | EW_STELLAR) && (!activated_coda || stellar_glimmer_state == 0) {
            return builder.none();
        }
        // 命座伤害条件
        if s == C1 && context.character_common_data.constellation < 1 {
            return builder.none();
        }
        if s == C4 && context.character_common_data.constellation < 4 {
            return builder.none();
        }

        // 星反应类型判定：辉映·星扩散（state 2）为星扩散，其余（无辉映/辉映·星超导）为星超导
        let is_stellar_swirl = stellar_glimmer_state == 2;

        let ratio = match s {
            A1 => ODETTE_SKILL.a_dmg1[s1],
            A2 => ODETTE_SKILL.a_dmg2[s1],
            A31 => ODETTE_SKILL.a_dmg31[s1],
            A32 => ODETTE_SKILL.a_dmg32[s1],
            A4 => ODETTE_SKILL.a_dmg4[s1],
            A5 => ODETTE_SKILL.a_dmg5[s1],
            Z => ODETTE_SKILL.z_dmg[s1],
            X1 => ODETTE_SKILL.x_dmg1[s1],
            X2 => ODETTE_SKILL.x_dmg2[s1],
            X3 => ODETTE_SKILL.x_dmg3[s1],
            E => ODETTE_SKILL.e_dmg[s2],
            EC_DOT => ODETTE_SKILL.e_coda_dot[s2],
            EC => if is_stellar_swirl {
                ODETTE_SKILL.e_coda_ss[s2]
            } else {
                ODETTE_SKILL.e_coda_sc[s2]
            },
            EP => ODETTE_SKILL.e_plume_dmg[s2],
            EP_STELLAR => if stellar_glimmer_state == 1 {
                ODETTE_SKILL.e_plume_sc[s2]
            } else {
                ODETTE_SKILL.e_plume_ss[s2]
            },
            EW => ODETTE_SKILL.e_wing_dmg[s2],
            EW_STELLAR => if stellar_glimmer_state == 1 {
                ODETTE_SKILL.e_wing_sc[s2]
            } else {
                ODETTE_SKILL.e_wing_ss[s2]
            },
            Q => ODETTE_SKILL.q_slash[s3],
            Q_TOTAL => ODETTE_SKILL.q_slash[s3] * 3.0,
            QF => ODETTE_SKILL.q_final[s3],
            C1 => if is_stellar_swirl {
                ODETTE_SKILL.c1_ss_atk
            } else {
                ODETTE_SKILL.c1_sc_atk
            },
            C4 => if is_stellar_swirl {
                ODETTE_SKILL.c4_ss_atk
            } else {
                ODETTE_SKILL.c4_sc_atk
            },
        };

        builder.add_atk_ratio("技能倍率", ratio);

        if let Some(elevative_type) = s.get_elevative_type(stellar_glimmer_state) {
            builder.elevative(
                &context.attribute,
                &context.enemy,
                s.get_element(),
                elevative_type,
                SkillType::Elevative,
                context.character_common_data.level,
                fumo,
            )
        } else {
            builder.damage(
                &context.attribute,
                &context.enemy,
                s.get_element(),
                s.get_skill_type(),
                context.character_common_data.level,
                fumo,
            )
        }
    }

    fn new_effect<A: Attribute>(common_data: &CharacterCommonData, config: &CharacterConfig) -> Option<Box<dyn ChangeAttribute<A>>> {
        let (stellar_glimmer_state, stellar_conduct_application_count, marvelous_splendor_self, marvelous_splendor_other) = match *config {
            CharacterConfig::Odette { stellar_glimmer_state, stellar_conduct_application_count, marvelous_splendor_self, marvelous_splendor_other } =>
                (stellar_glimmer_state, stellar_conduct_application_count, marvelous_splendor_self, marvelous_splendor_other),
            _ => (0, 0, 0.0, 0.0),
        };
        // 「华彩」层数上限：基础召唤为4层，命座1额外获得2层（共6层），非1命角色钳制为4层
        let max_stacks = if common_data.constellation >= 1 { 6.0 } else { 4.0 };
        let marvelous_splendor_self = marvelous_splendor_self.min(max_stacks);
        let marvelous_splendor_other = marvelous_splendor_other.min(max_stacks);
        Some(Box::new(OdetteEffect {
            stellar_glimmer_state,
            stellar_conduct_application_count,
            marvelous_splendor_self,
            marvelous_splendor_other,
            common_data: common_data.clone(),
        }))
    }

